import{_ as n,o as i,c as a,a0 as t}from"./chunks/framework.CzVS_xMp.js";const u=JSON.parse('{"title":"Deep Learning for Network Engineers","description":"","frontmatter":{},"headers":[],"relativePath":"courses/deep-learning-for-network-engineers/index.md","filePath":"courses/deep-learning-for-network-engineers/index.md","lastUpdated":1788490169000}'),r={name:"courses/deep-learning-for-network-engineers/index.md"};function o(s,e,d,l,c,p){return i(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="deep-learning-for-network-engineers" tabindex="-1">Deep Learning for Network Engineers <a class="header-anchor" href="#deep-learning-for-network-engineers" aria-label="Permalink to &quot;Deep Learning for Network Engineers&quot;">​</a></h1><p>A six-week engineering study of how deep learning workloads shape GPU communication, distributed training, and AI data center backend networks.</p><img width="1672" height="941" alt="image" src="https://github.com/user-attachments/assets/c4f68d13-1942-436a-bbe0-35f360da5456"><ul><li><p>[Week 1: From Artificial Neuron to AI Training Fabric](./week01/ Revisit artificial neurons, forward pass, backward pass, gradients, and weight updates from an infrastructure perspective. The key focus is understanding why training eventually leads to GPU memory pressure and distributed synchronization.</p></li><li><p>[Week 2: Introduction to Large Language Models and Training](./week02/ Study tokenization, embeddings, Transformer basics, attention, feed-forward layers, and next-token prediction. The goal is to understand why LLMs require large GPU memory, high compute throughput, and scalable distributed training.</p></li><li><p>[Week 3: Parallelism Strategy and Communication Primitives](./week03/ Study data parallelism, tensor parallelism, pipeline parallelism, and the communication patterns behind them. The focus is on how AllReduce, ReduceScatter, AllGather, and activation transfers affect GPU cluster performance.</p></li><li><p>[Week 4: RDMA, RoCE, and NCCL Communication](./week04/ Connect distributed training with RDMA-based GPU-to-GPU communication. The goal is to understand how NCCL uses high-speed backend networks and why low latency, high throughput, and lossless transport matter.</p></li><li><p>Week 5: Congestion Control and AI Fabric Reliability Study the operational challenges of AI fabrics, including packet loss, congestion, PFC, ECN, DCQCN, head-of-line blocking, and hash polarization. The focus is on why AI training networks require careful congestion control and validation</p></li><li><p>Week 6: Backend Network Topology and Design Review Study backend topology choices such as shared NIC, NIC-per-GPU, single-rail, dual-rail, and rail-optimized designs. The final goal is to produce an AI training fabric design review from the perspective of an MLOps/LLOps engineer.</p></li></ul>',4)])])}const h=n(r,[["render",o]]);export{u as __pageData,h as default};
